public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Arrays.asList(nums[0]));
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        int[] remainingNums = Arrays.copyOf(nums, nums.length - 1);
        Arrays.sort(remainingNums);
        for (int j = 0; j < remainingNums.length; j++) {
            if (remainingNums[j] != num) {
                List<Integer> currentPermutation = new ArrayList<>();
                currentPermutation.add(num);
                currentPermutation.addAll(Arrays.asList(remainingNums).subList(0, j).stream().map(n -> n).collect(Collectors.toList()));
                currentPermutation.addAll(Arrays.asList(remainingNums).subList(j, remainingNums.length).stream().map(n -> n).collect(Collectors.toList()));
                result.add(currentPermutation);
            }
        }
    }
    return result;
}
