private void permute(int[] nums, int start, List<List<Integer>> result, List<Integer> curr) {
    if (start == nums.length) {
        result.add(new ArrayList<>(curr));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        curr.add(nums[i]);
        permute(nums, i + 1, result, curr);
        curr.remove(curr.size() - 1);
    }
