public class Permute {
    public List<List<Integer>> permute(int[] nums) {
        if (nums.length == 1) {
            List<List<Integer>> result = new ArrayList<>();
            List<Integer> list = new ArrayList<>();
            list.add(nums[0]);
            result.add(list);
            return result;
        } else {
            List<List<Integer>> permutations = new ArrayList<>();
            for (int i = 0; i < nums.length; i++) {
                int num = nums[i];
                List<Integer> rest = Arrays.stream(nums).filter(n -> n != num).boxed().collect(Collectors.toList());
                List<List<Integer>> subPermutations = permute(rest.stream().mapToInt(Integer::intValue).toArray());
                for (List<Integer> subPermutation : subPermutations) {
                    List<Integer> permutation = new ArrayList<>();
                    permutation.add(num);
                    permutation.addAll(subPermutation);
                    permutations.add(permutation);
                }
            }
            return permutations;
        }
    }
}
