public static int countOilDeposits(char[][] grid) {
    // Initialize a set to keep track of visited cells
    Set<String> visited = new HashSet<>();

    // Iterate over each cell in the grid
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell is an oil pocket, add it to the set
            if (grid[i][j] == '@') {
                visited.add(i + "," + j);
            }
        }
    }

    // Iterate over each cell again
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell is a wild card, check if any of its neighbors are in the set
            if (grid[i][j] == '*') {
                for (int x = -1; x <= 1; x++) {
                    for (int y = -1; y <= 1; y++) {
                        if (i + x >= 0 && i + x < grid.length && j + y >= 0 && j + y < grid[i].length && visited.contains(i + x + "," + j + y)) {
                            // If any neighbor is in the set, add the current cell to the set
                            visited.add(i + "," + j);
                            break;
                        }
                    }
                }
            }
        }
    }

    // Return the size of the set, which is the number of distinct oil deposits
    return visited.size();
}
