public static int countOilDeposits(char[][] grid) {
    // Initialize a set to keep track of distinct oil deposits
    Set<String> oilDeposits = new HashSet<>();

    // Iterate over each row of the grid
    for (int i = 0; i < grid.length; i++) {
        // Initialize a bitset to keep track of visited cells
        BitSet visited = new BitSet(grid[i].length);

        // Iterate over each cell in the row
        for (int j = 0; j < grid[i].length; j++) {
            // If the cell is '@', mark it as visited and update the set of oil deposits
            if (grid[i][j] == '@') {
                visited.set(j);
                oilDeposits.add(i + ";" + j);
            }
        }

        // Iterate over each cell in the row from the end to the start, starting from the first unvisited cell
        for (int j = grid[i].length - 1; j >= 0; j--) {
            if (!visited.get(j)) {
                // If the cell is '@', mark it as visited and update the set of oil deposits
                if (grid[i][j] == '@') {
                    visited.set(j);
                    oilDeposits.add(i + ";" + j);
                }
                // If the cell is '*', mark all cells in the same row as visited and update the set of oil deposits
                else if (grid[i][j] == '*') {
                    visited.set(0, grid[i].length);
                    oilDeposits.add(i + ";" + j);
                }
            }
        }
    }

    // Return the size of the set of oil deposits
    return oilDeposits.size();
}
