class Algorithms {
  public static int maxRegions(int N) {
    int sqrtN = (int) Math.sqrt(N) + 1;
    int regions = 1;
    for (int i = 2; i <= sqrtN; i++) {
      int multiples = N / i;
      if (multiples * i == N) {
        regions = Math.max(regions, 2 * multiples);
      } else {
        while (multiples > 0) {
          regions++;
          multiples--;
        }
      }
    }
    return regions;
  }
}
