public static int maxRegions(int N) {
    // Handle invalid input
    if (N < 0) {
        throw new IllegalArgumentException("N must be non-negative");
    }

    // Base case: N = 0
    if (N == 0) {
        return 1;
    }

    // Recursive case: N > 0
    int maxRegions = 0;
    for (int i = 0; i < N; i++) {
        maxRegions = Math.max(maxRegions, maxRegions(N - 1) * 2);
    }
    return maxRegions + 1;
}
