public static List<Integer> generateFibonacciSequence(int N) {
    // Handle invalid input
    if (N < 0) {
        return null;
    }

    List<Integer> sequence = new ArrayList<>();
    if (N == 0) {
        // Base case: N = 0
        return sequence;
    } else if (N == 1) {
        // Base case: N = 1
        sequence.add(0);
        return sequence;
    } else if (N == 2) {
        // Base case: N = 2
        sequence.add(0);
        sequence.add(1);
        return sequence;
    }

    // Initialize variables for recurrence
    int fib0 = 0;
    int fib1 = 1;
    for (int i = 2; i <= N; i++) {
        // Recursive case: N > 2
        int fibi = fib0 + fib1;
        fib0 = fib1;
        fib1 = fibi;
        sequence.add(fibi);
    }
    return sequence;
