public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a Set to store the visited n-tersections
  Set<int[]> visited = new HashSet<>();

  // Add the starting n-tersection to the Set
  visited.add(start);

  // Create a queue to hold the n-tersections to be visited
  Queue<int[]> queue = new LinkedList<>();
  queue.add(start);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Get the current n-tersection
    int[] current = queue.poll();

    // Check if the current n-tersection is the ending n-tersection
    if (Arrays.equals(current, end)) {
      return "can be travelled";
    }

    // Visit all the adjacent n-tersections of the current n-tersection
    for (int[] adjacent : getAdjacentNIntersections(current, paths)) {
      // Check if the adjacent n-tersection has already been visited
      if (!visited.contains(adjacent)) {
        // Add the adjacent n-tersection to the Set of visited n-tersections
        visited.add(adjacent);

        // Add the adjacent n-tersection to the queue
        queue.add(adjacent);
      }
    }
  }

  // If the queue is empty, return "cannot be travelled"
  return "cannot be travelled";
}

private static int[][] getAdjacentNIntersections(int[] intersection, int[][] paths) {
  // Create a Set to store the adjacent n-tersections
  Set<int[]> adjacent = new HashSet<>();

  // Loop through the paths
  for (int[] path : paths) {
    // Check if the current path starts at the given intersection
    if (Arrays.equals(intersection, path[0])) {
      // Add the end of the path to the Set of adjacent n-tersections
      adjacent.add(path[1]);
    }

    // Check if the current path ends at the given intersection
    if (Arrays.equals(intersection, path[1])) {
      // Add the start of the path to the Set of adjacent n-tersections
      adjacent.add(path[0]);
    }
  }

  // Return the Set of adjacent n-tersections as an array
  return adjacent.toArray(new int[adjacent.size()][]);
