  }

  // Check if the starting and ending points are the same
  if (start[0] == end[0] && start[1] == end[1]) {
    return "can be travelled";
  }

  // Check if the maze is big enough to hold both starting and ending points
  if (n <= start[0] || n <= start[1] || n <= end[0] || n <= end[1]) {
    return "cannot be travelled";
  }

  // Check if the paths are valid
  for (int[] path : paths) {
    // Check if the starting point is not a point along the path
    if (path[0] == start[0] && path[1] == start[1]) {
      return "cannot be travelled";
    }

    // Check if the ending point is not a point along the path
    if (path[0] == end[0] && path[1] == end[1]) {
      return "cannot be travelled";
