    // Check if the starting and ending points are both on the same row or column
    if ((start[0] == path[0] && start[1] != path[1]) || (start[0] != path[0] && start[1] == path[1]) || (end[0] == path[0] && end[1] != path[1]) || (end[0] != path[0] && end[1] == path[1])) {
