  }

  // Check if the maze has a path between the starting and ending points
  for (int i = 0; i < n - 1; i++) {
    for (int j = 0; j < n - 1; j++) {
      if (paths[(i * n) + j][0] == start[0] && paths[(i * n) + j][1] == start[1] && paths[(i * n) + j][2] == end[0] && paths[(i * n) + j][3] == end[1]) {
