    for (int i = 0; i < word1Length; i++) {
        for (int j = 0; j < word2Length; j++) {
            // Check if the letters match
            if (word1.charAt(i) == word2.charAt(j)) {
                // Increment the number of common letters
                commonLetters++;
            }
        }
    }

    // Calculate the approximate value as a reduced fraction
    int gcd = gcd(word1Length, word2Length);
    int numerator = commonLetters;
    int denominator = (word1Length * word2Length) / gcd;

    return numerator + "/" + denominator;
