public int search(int[] nums, int target) {
    // Find the pivot index
    int pivot = findPivot(nums);

    // Search in the left part of the array
    if (target < nums[pivot]) {
        return searchLeft(nums, target, 0, pivot - 1);
    }

    // Search in the right part of the array
    if (target > nums[pivot]) {
        return searchRight(nums, target, pivot + 1, nums.length - 1);
    }

    // If we reach this point, we have found the target
    return pivot;
}

// Find the pivot index
private int findPivot(int[] nums) {
    // The pivot is the first element
    if (nums[0] < nums[nums.length - 1]) {
        return 0;
    }

    // The pivot is the last element
    if (nums[0] > nums[nums.length - 1]) {
        return nums.length - 1;
    }

    // The pivot is in the middle of the array
    for (int i = 1; i < nums.length - 1; i++) {
        if (nums[i] < nums[i - 1]) {
            return i;
        }
    }

    // We couldn't find the pivot
    return -1;
}

// Search in the left part of the array
private int searchLeft(int[] nums, int target, int left, int right) {
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] < target) {
            left = mid + 1;
        } else if (nums[mid] > target) {
            right = mid - 1;
        } else {
            return mid;
        }
    }

    // The target is not in the left part of the array
    return -1;
}

// Search in the right part of the array
private int searchRight(int[] nums, int target, int left, int right) {
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] < target) {
            left = mid + 1;
        } else if (nums[mid] > target) {
            right = mid - 1;
        } else {
            return mid;
        }
    }

    // The target is not in the right part of the array
    return -1;
}
