public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Remove the smallest 5% of elements from the array
    int smallest = (int) (arr.length * 0.05);
    for (int i = 0; i < smallest; i++) {
        arr[i] = 0;
    }

    // Remove the largest 5% of elements from the array
    int largest = (int) (arr.length * 0.05);
    for (int i = arr.length - 1; i >= arr.length - largest; i--) {
        arr[i] = 0;
    }

    // Calculate the mean of the remaining elements
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    return mean / (arr.length - smallest - largest);
}
