public class TrimMean {

    public static double trimMean(int[] arr) {
        // 1. Sort the array in ascending order
        Arrays.sort(arr);

        // 2. Calculate the first 5% and last 5% of the values
        int numElements = arr.length;
        int firstFivePercent = (int) (numElements * 0.05);
        int lastFivePercent = (int) (numElements * 0.05);
        int firstIndices = numElements - firstFivePercent;
        int lastIndices = firstFivePercent;

        // 3. Calculate the mean of the remaining elements
        double sum = 0;
        for (int i = firstIndices; i < lastIndices; i++) {
            sum += arr[i];
        }
        double mean = sum / (numElements - (firstFivePercent + lastFivePercent));

        return mean;
