public double trimMean(int[] arr) {
    // Sort the input array in ascending order
    Arrays.sort(arr);

    // Calculate the mean of the top 90% of the array
    int startIndex = (int) (0.9 * arr.length);
    double mean = 0;
    for (int i = startIndex; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= (arr.length - startIndex);

    // Calculate the mean of the bottom 90% of the array
    int endIndex = (int) (0.1 * arr.length);
    for (int i = 0; i < endIndex; i++) {
        mean -= arr[i];
