package com.company;

import java.util.Arrays;
import java.util.stream.IntStream;

// See: https://www.youtube.com/watch?v=Tkw38haLOi4

/**
 * Given an integer array arr and a divisor k, write a function to check if it is possible to divide the array into n / 2 pairs such that the sum of each pair is divisible by k.

 * @param arr The input integer array
 * @param k The divisor
 * @return true if it is possible, otherwise false
 */
public class CanArrange
{
    public static boolean canArrange(int[] arr, int k)
    {
        // Check if the divisor k is evenly divisible by n/2
        if (arr.length % 2 != 0 && k % (arr.length / 2) != 0)
        {
            return false;
        }

        // Check if all elements in the array are evenly divisible by k
        int[] evenDivisors = new int[arr.length];
        for (int i = 0; i < arr.length; i++)
        {
            evenDivisors[i] = arr[i] % k;
        }
        if (IntStream.of(evenDivisors).anyMatch(b -> b != 0))
        {
            return false;
        }

        // Check if the sum of each pair is divisible by k
        for (int i = 0; i < arr.length - 1; i += 2)
        {
            if (arr[i] + arr[i + 1] % k != 0)
            {
                return false;
            }
        }

        return true;
    }
}

