public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (!allEqual(arr)) {
        minOperations++;
        // Find two indices x and y with arr[x] != arr[y]
        // and subtract 1 from arr[x] and add 1 to arr[y]
        int x = findFirstIndexGreaterThan(arr, arr[y]);
        int y = findFirstIndexGreaterThan(arr, arr[x]);
        arr[x] -= 1;
        arr[y] += 1;
    }
    return minOperations;
}

private boolean allEqual(int[] arr) {
    int firstElement = arr[0];
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != firstElement) {
