  for (int i = 1; i <= (int)Math.sqrt(n); i++) {
    // Check if i is a factor of n
    if (n % i == 0) {
      // If it is, add it to the set
      factors.add(i);
      // If we have found k factors, return the kth factor
      if (factors.size() == k) {
        return factors.toArray()[k - 1];
