public String getSmallestString(int n, int k) {
  // Initialize an array to store the characters of the string
  char[] chars = new char[n];

  // Initialize the value of the first character
  int value = k;

  // Initialize the index of the first character
  int index = 0;

  // While there are still characters to add to the string
  while (index < n) {
    // Calculate the value of the next character
    int nextValue = value % 26;

    // If the next value is 0, it means we have reached the end of the alphabet
    // In this case, we will add a letter that is one less than the previous letter
    if (nextValue == 0) {
      chars[index] = (char) (chars[index - 1] - 1);
    } else {
      chars[index] = (char) (nextValue + 'a' - 1);
    }

    // Increment the value of the next character
    value = value / 26;

    // Increment the index of the next character
    index++;
  }

  // Return the resulting string
  return new String(chars);
}

