package org.leetcode.problems;

public class LongestLine {  
  public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
      for (int j = 0; j < mat[i].length; j++) {
        if (mat[i][j] == 1) {
          maxLength = Math.max(maxLength, getLongestSequenceLength(mat, i, j));
        }
      }
    }
    return maxLength;
  }

  private static int getLongestSequenceLength(int[][] mat, int i, int j) {
    int length = 1;
    boolean[][] visited = new boolean[mat.length][mat[0].length];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[]{i, j});
    visited[i][j] = true;
    while (!queue.isEmpty()) {
      int[] current = queue.poll();
      int x = current[0];
      int y = current[1];
      if (x - 1 >= 0 && !visited[x - 1][y] && mat[x - 1][y] == 1) {
        queue.offer(new int[]{x - 1, y});
        visited[x - 1][y] = true;
        length++;
      }
      if (x + 1 < mat.length && !visited[x + 1][y] && mat[x + 1][y] == 1) {
        queue.offer(new int[]{x + 1, y});
        visited[x + 1][y] = true;
        length++;
      }
      if (y - 1 >= 0 && !visited[x][y - 1] && mat[x][y - 1] == 1) {
        queue.offer(new int[]{x, y - 1});
        visited[x][y - 1] = true;
        length++;
      }
      if (y + 1 < mat[0].length && !visited[x][y + 1] && mat[x][y + 1] == 1) {
        queue.offer(new int[]{x, y + 1});
        visited[x][y + 1] = true;
        length++;
      }
    }
    return length;
  }
}

