import java.util.HashSet;
import java.util.List;
import java.util.Set;

     public class Solution {
          public int squarePermutations(int[] A) {
               // Calculate the sum of each pair of adjacent elements in the array
               int[] prefixSums = new int[A.length];
               prefixSums[0] = A[0];
               for (int i = 1; i < A.length; i++) {
                    prefixSums[i] = A[i] + prefixSums[i - 1];
               }
               Set<Integer> uniquePrefixSums = new HashSet<>(prefixSums.length);
               for (int prefixSum : prefixSums) {
                    int root = (int) Math.floor(Math.sqrt(prefixSum));
                    if (root * root == prefixSum) {
                         uniquePrefixSums.add(prefixSum);
                    }
               }
               // Calculate the number of permutations of the unique prefix sums
               List<Integer> permutations = new ArrayList<>(uniquePrefixSums);
               int permutationsCount = 1;
               for (int i = 0; i < permutations.size(); i++) {
                    int count = 1;
                    for (int j = i + 1; j < permutations.size(); j++) {
                         if (permutations.get(i) < permutations.get(j)) {
                              count++;
                         }
                    }
                    permutationsCount *= count;
               }
               return permutationsCount;
          }
     }
}

public static int squarePermutations(int[] A) {
    // Initialize a set to store unique permutations
    Set<int[]> permutations = new HashSet<>();

    // Sort the input array in ascending order
    Arrays.sort(A);

    // Initialize a variable to store the number of permutations
    int numPermutations = 1;

    // Iterate over the input array
    for (int i = 0; i < A.length; i++) {
        // Check if the current element is a perfect square
        if (Math.sqrt(A[i]) % 1 == 0) {
            // If it is, increment the number of permutations
            numPermutations++;

            // Add the current permutation to the set
            permutations.add(A.clone());

            // Iterate over the remaining elements and try to find a perfect square
            for (int j = i + 1; j < A.length; j++) {
                // If the current element is a perfect square, add the permutation to the set
                if (Math.sqrt(A[j]) % 1 == 0) {
                    permutations.add(A.clone());
                }
            }
        }
    }

    // Return the number of unique permutations
    return numPermutations;
}

