        if (sum * sum % 10 == 0) {
            result++;

            // Add the current index to the set of used indices
            usedIndices.add(i);
        }
    }

    // If there are no used indices, return 0
    if (usedIndices.isEmpty()) {
        return 0;
    }

    // Iterate over the remaining array elements that are not used
    for (int i = 0; i < A.length; i++) {
        if (!usedIndices.contains(i) && A[i] * A[i] % 10 == 0) {
            result++;
        }
    }

