    if (n < 10) {
        return -1;
    }

    // Sort the digits of n in ascending order
    int sortedN = n;
    for (int i = 0; i < 9; i++) {
        if (sortedN % 10 > sortedN / 10) {
            sortedN = sortedN % 10 + (sortedN / 10) * 10;
            i = -1;
        }
    }

    // If the sorted integer is greater than n, return it
    if (sortedN > n) {
        return sortedN;
