        if (currentChar != previousChar) {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        } else {
            currentEnergy++;
        }
        previousChar = currentChar;
    }

    return Math.max(maxEnergy, currentEnergy);
}
