    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);

        // If the current character is not the same as the previous character,
        // update the longest substring length and character
        if (currentChar != longestSubstringChar) {
            longestSubstringLength = i - longestSubstringLength;
            longestSubstringChar = currentChar;
        }

        // Update the longest substring length
        longestSubstringLength++;
    }

    // Return the length of the longest substring
    return longestSubstringLength;
}
