public static int minPerfectSquareSum(int n) {
    // Initialize a set to store the perfect square numbers
    Set<Integer> perfectSquares = new HashSet<>();

    // Calculate the sum of the perfect square numbers
    int sum = 0;

    // Loop until the sum is greater than or equal to the target
    while (sum < n) {
        // Calculate the next perfect square number
        int perfectSquare = (int) Math.sqrt(sum + 1) + 1;

        // Add the perfect square number to the set
        perfectSquares.add(perfectSquare);

        // Increment the sum by the perfect square number
        sum += perfectSquare;
    }

    // Return the minimum number of perfect square numbers
    return perfectSquares.size();
}
