      while (j >= 0) {
        if (perfectSquares[j]) {
          perfectSquares[i] = perfectSquares[j] + 1;
          break;
        }

        j--;
      }

      if (!perfectSquares[i]) {
        perfectSquares[i] = 1;
      }
